<script>
 import RegionState from './RegionState.svelte';import ScopePicker from './ScopePicker.svelte';import {createExportPreview} from '../export-preview';import {onDestroy} from 'svelte';import {FolderOpen,Download} from 'lucide-svelte';import {studio,current,liveAssets,importImages,editFor} from '../studio.svelte';import {stored,persist,rgb,hex} from '../api';import {selection} from '../stores/selection.svelte';import {project} from '../stores/project.svelte';import {tasks} from '../stores/tasks.svelte';import {previewExport,submitExport,exportPreviewInput,chooseExportDirectory} from '../services/export.js';
 const defaults=()=>({format:'webp',width:1000,height:1000,fit:'pad',quality:92,maxBytes:800000,outputDir:'',background:[255,255,255]});let preset=$state(stored('export',defaults())),limit=$state(preset.maxBytes>0),submitting=$state(false),taskId=$state(null),submitError=$state(''),folderError=$state('');const context=$derived(selection.context||selection.snapshot()),ids=$derived(context.resolvedTarget.ids),leadId=$derived(ids.includes(studio.aid)?studio.aid:ids[0]),lead=$derived(current()?.assets.find(a=>a.id===leadId)),activeTask=$derived(taskId&&['queued','running','waiting','cancelling'].includes(tasks.byId[taskId]?.state));
 const errors=$derived([!Number.isInteger(preset.width)||preset.width<1||preset.width>16000?'宽度必须为1至16000像素。':'',!Number.isInteger(preset.height)||preset.height<1||preset.height>16000?'高度必须为1至16000像素。':'',preset.width*preset.height>120000000?'图片总像素不能超过1.2亿。':'',limit&&(!Number.isFinite(preset.maxBytes)||preset.maxBytes<1000||preset.maxBytes>1000000000)?'文件大小上限应为1KB至1GB。':'',preset.format!=='png'&&(!Number.isInteger(preset.quality)||preset.quality<1||preset.quality>100)?'图片质量必须为1至100的整数。':''].filter(Boolean));
 let previewAttempt=$state(0),encoded=$state({loading:false,result:null,error:''}),showBefore=$state(false);const previewController=createExportPreview({request:previewExport,onChange:value=>encoded=value});onDestroy(()=>previewController.dispose());
 $effect(()=>{previewAttempt;studio.dataRoot;lead?.generatedBase;const ready=studio.mode==='export'&&!studio.busy&&lead&&!errors.length;const input=ready?exportPreviewInput(studio.pid,context,leadId,preset,leadId===studio.aid?studio.draft:editFor(lead),limit):null;previewController.set(input);});
 async function choose(){folderError='';try{await chooseExportDirectory();}catch(error){if(error.name!=='AbortError')folderError=error.message;}}
 async function exportNow(){if(submitting||activeTask||errors.length||!ids.length)return;submitting=true;submitError='';try{persist('export',preset);const result=await submitExport(preset,{limit});taskId=result?.task?.id||null;}catch(error){submitError=error.message;}finally{submitting=false;}}
 function reset(){preset=defaults();limit=true;persist('export',preset);}
</script>
{#if !liveAssets().length}<div class="workflow-panel"><div class="empty"><h2>没有可导出的图片</h2><button class="primary" onclick={()=>importImages(false)}>导入图片</button></div></div>{:else}<div class="workflow-panel export-panel" inert={!!studio.busy}><div class="workflow-heading"><h1>导出</h1></div><ScopePicker/><div class="export-layout"><div class="export-preview"><div class="segmented" role="group" aria-label="导出效果对比"><button class:active={!showBefore} aria-pressed={!showBefore} onclick={()=>showBefore=false}>导出后</button><button class:active={showBefore} aria-pressed={showBefore} onclick={()=>showBefore=true}>导出前</button></div>{#if encoded.result}<img src={showBefore?encoded.result.beforeUrl:encoded.result.url} alt={showBefore?"调整导出设置前":"实际导出效果"}/><span>{encoded.result.width} × {encoded.result.height} · {preset.format.toUpperCase()} · {encoded.result.bytes.toLocaleString()} bytes{#if preset.format!=='png'} · Quality {encoded.result.quality}{/if}</span>{#if encoded.result.status!=='ok'}<p class="field-error" role="status">文件仍超过大小上限。请提高上限或调整导出设置。</p>{/if}{:else if encoded.loading}<RegionState compact state="loading" title="正在生成导出预览"/>{:else if encoded.error}<RegionState compact state="error" title="无法读取导出效果" message={encoded.error} onretry={()=>previewAttempt++}/>{:else}<p class="hint">请先修正导出设置。</p>{/if}<span>{lead?.name}</span>{#if ids.length>1}<span>{ids.length} 张图片使用这些导出设置</span>{/if}</div><div class="export-form"><div class="section-row"><h3>导出后</h3><button class="text-button" type="button" onclick={reset}>恢复默认设置</button></div><label>图片格式<select aria-label="导出格式" bind:value={preset.format}><option value="webp">WebP</option><option value="jpeg">JPEG</option><option value="png">PNG</option></select></label><div class="field-grid"><label>宽度<input type="number" aria-label="导出宽度" min="1" max="16000" step="1" bind:value={preset.width}/></label><label>高度<input type="number" aria-label="导出高度" min="1" max="16000" step="1" bind:value={preset.height}/></label></div><label>画面适配方式<select aria-label="导出适配方式" bind:value={preset.fit}><option value="pad">补边：保留完整图片</option><option value="crop">裁切：填满画面</option></select></label><label>背景颜色<input type="color" value={hex(preset.background)} onchange={e=>preset.background=rgb(e.target.value)}/></label>{#if preset.format!=='png'}<label>图片质量<input aria-label="导出质量" type="number" min="1" max="100" bind:value={preset.quality}/></label>{/if}<label class="checkbox-label"><input type="checkbox" bind:checked={limit}/>限制文件大小</label>{#if limit}<label>最大文件大小（KB）<input aria-label="最大文件大小（KB）" type="number" min="1" value={preset.maxBytes/1000} oninput={e=>preset.maxBytes=Number(e.target.value)*1000}/></label>{#if preset.format==='png'}<p class="hint">PNG 使用无损压缩。若超过大小上限，请缩小尺寸或改用 WebP。</p>{/if}{/if}<label>文件夹<div class="input-action"><input aria-label="保存文件夹" readonly value={project.directoryHandle?.name||''} placeholder="未授权，可下载结果"/><button aria-label="选择保存文件夹" title="选择或更换结果保存文件夹" onclick={choose}><FolderOpen size={17}/></button></div></label><p class="hint">结果写回已授权的项目文件夹；也可在对话中保存或下载。</p>{#if folderError}<p class="field-error" role="alert">{folderError}</p>{/if}{#each errors as error}<p class="field-error" role="status">{error}</p>{/each}<button class="primary full" disabled={submitting||activeTask||!!studio.busy||!ids.length||!!errors.length} onclick={exportNow}><Download size={16}/>导出 {ids.length} {ids.length===1?'张图片':'张图片'}</button><p class="hint" role="status">进度和交付文件在右侧对话更新。</p>{#if submitError}<p class="field-error" role="alert">{submitError}</p><button class="line-button" onclick={exportNow}>重试导出</button>{/if}</div></div></div>
{/if}

